#include <stddef.h>

#include "ui_service.h"
#include "esp_log.h"

#if UI_SERVICE_HAS_SQUARELINE
#include "ui.h" /* Generated by SquareLine Studio into app/ui_service/ui/. */
#if UI_SERVICE_HAS_ADMIN_UI
#include "ui_service_admin.h"
#endif
#else
#include "ui_service_fallback.h"
#endif

/***********************************************************************************************************************
 * Macro definitions
 **********************************************************************************************************************/

#define UI_SERVICE_TAG "UI_SERVICE"

/***********************************************************************************************************************
 * Public APIs
 **********************************************************************************************************************/

/***********************************************************************************************************************
 * Builds the first screen: SquareLine's ui_init(), or the built-in test screen without an export.
 *
 * @param[in,out] p_ctrl  Pointer to the caller-owned runtime control block.
 * @param[in]     p_cfg   Configuration that remains valid and unchanged for the lifetime of the instance.
 *
 * @retval APP_SUCCESS              The screen is loaded.
 * @retval APP_ERR_INVALID_POINTER  A required API argument is NULL.
 * @retval APP_ERR_INVALID_STATE    The control block is already initialized, or the LVGL port is not.
 * @retval APP_ERR_TIMEOUT          The LVGL lock was not available.
 **********************************************************************************************************************/
app_err_t ui_service_init(ui_service_instance_ctrl_t *const p_ctrl, const ui_service_config_t *const p_cfg)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ASSERT(NULL != p_cfg);
    APP_ASSERT(NULL != p_cfg->p_lvgl);
    APP_ERROR_RETURN(false == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

    const app_err_t ret = lvgl_port_lock(p_cfg->p_lvgl, UI_SERVICE_INIT_LOCK_TIMEOUT_MS);
    if (APP_SUCCESS != ret)
    {
        return ret;
    }

    ui_init();
    lvgl_port_unlock(p_cfg->p_lvgl);

    p_ctrl->p_cfg = p_cfg;
    p_ctrl->init  = true;

    ESP_LOGI(UI_SERVICE_TAG,
             "%s%s",
             ui_service_has_squareline() ? "SquareLine UI loaded"
                                         : "No SquareLine export in app/ui_service/ui: test screen",
             ui_service_has_admin_ui() ? ", admin UI included" : "");
    return APP_SUCCESS;
}

/***********************************************************************************************************************
 * Reports whether the build contains a SquareLine export (decided by app/ui_service/CMakeLists.txt).
 **********************************************************************************************************************/
bool ui_service_has_squareline(void)
{
    return (0 != UI_SERVICE_HAS_SQUARELINE);
}

/***********************************************************************************************************************
 * Reports whether the build contains the admin export (decided by app/ui_service/CMakeLists.txt).
 **********************************************************************************************************************/
bool ui_service_has_admin_ui(void)
{
    return (0 != UI_SERVICE_HAS_ADMIN_UI);
}

/***********************************************************************************************************************
 * Shows AdminLogin, the first screen of the admin project. Only the screen changes: checking the admin ID and password
 * stays with the caller and is done locally, never over MQTT.
 *
 * @param[in,out] p_ctrl  Pointer to an initialized runtime control block.
 *
 * @retval APP_SUCCESS              AdminLogin is shown.
 * @retval APP_ERR_INVALID_POINTER  The control pointer is NULL.
 * @retval APP_ERR_INVALID_STATE    The control block is not initialized.
 * @retval APP_ERR_NOT_SUPPORTED    The build has no admin export.
 * @retval APP_ERR_TIMEOUT          The LVGL lock was not available.
 **********************************************************************************************************************/
app_err_t ui_service_show_admin(ui_service_instance_ctrl_t *const p_ctrl)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

#if UI_SERVICE_HAS_ADMIN_UI
    const app_err_t ret = lvgl_port_lock(p_ctrl->p_cfg->p_lvgl, UI_SERVICE_SCREEN_LOCK_TIMEOUT_MS);
    if (APP_SUCCESS != ret)
    {
        return ret;
    }

    ui_service_admin_open();
    lvgl_port_unlock(p_ctrl->p_cfg->p_lvgl);
    return APP_SUCCESS;
#else
    return APP_ERR_NOT_SUPPORTED;
#endif
}

/***********************************************************************************************************************
 * Shows Home, e.g. when leaving admin mode. The admin screen that was shown is Temporary and deletes itself.
 *
 * @param[in,out] p_ctrl  Pointer to an initialized runtime control block.
 *
 * @retval APP_SUCCESS              Home is shown.
 * @retval APP_ERR_INVALID_POINTER  The control pointer is NULL.
 * @retval APP_ERR_INVALID_STATE    The control block is not initialized.
 * @retval APP_ERR_NOT_SUPPORTED    The build has no SquareLine export (test screen only).
 * @retval APP_ERR_TIMEOUT          The LVGL lock was not available.
 **********************************************************************************************************************/
app_err_t ui_service_show_home(ui_service_instance_ctrl_t *const p_ctrl)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

#if UI_SERVICE_HAS_SQUARELINE
    const app_err_t ret = lvgl_port_lock(p_ctrl->p_cfg->p_lvgl, UI_SERVICE_SCREEN_LOCK_TIMEOUT_MS);
    if (APP_SUCCESS != ret)
    {
        return ret;
    }

    _ui_screen_change(&ui_Home, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_Home_screen_init);
    lvgl_port_unlock(p_ctrl->p_cfg->p_lvgl);
    return APP_SUCCESS;
#else
    return APP_ERR_NOT_SUPPORTED;
#endif
}

/***********************************************************************************************************************
 * Maps one 4x3 keypad character to an LVGL key and queues it for the focused object.
 *
 * @param[in,out] p_ctrl  Pointer to an initialized runtime control block.
 * @param[in]     key     '0'-'9', UI_SERVICE_KEY_CHAR_ENTER or UI_SERVICE_KEY_CHAR_BACKSPACE.
 *
 * @retval APP_SUCCESS               The key was queued.
 * @retval APP_ERR_INVALID_POINTER   The control pointer is NULL.
 * @retval APP_ERR_INVALID_STATE     The control block is not initialized.
 * @retval APP_ERR_INVALID_ARGUMENT  The character is not a keypad key.
 * @retval APP_ERR_TIMEOUT           The key queue is full; the key was dropped.
 **********************************************************************************************************************/
app_err_t ui_service_post_keypad_char(ui_service_instance_ctrl_t *const p_ctrl, char key)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

    uint32_t lv_key;

    if ((key >= '0') && (key <= '9'))
    {
        lv_key = (uint32_t)key;
    }
    else if (UI_SERVICE_KEY_CHAR_ENTER == key)
    {
        lv_key = LV_KEY_ENTER;
    }
    else if (UI_SERVICE_KEY_CHAR_BACKSPACE == key)
    {
        lv_key = LV_KEY_BACKSPACE;
    }
    else
    {
        return APP_ERR_INVALID_ARGUMENT;
    }

    return lvgl_port_post_key(p_ctrl->p_cfg->p_lvgl, lv_key);
}

/***********************************************************************************************************************
 * Takes the LVGL lock for changing UI objects from a task other than the LVGL task. See lvgl_port_lock().
 **********************************************************************************************************************/
app_err_t ui_service_lock(ui_service_instance_ctrl_t *const p_ctrl, uint32_t timeout_ms)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

    return lvgl_port_lock(p_ctrl->p_cfg->p_lvgl, timeout_ms);
}

/***********************************************************************************************************************
 * Releases the lock taken by ui_service_lock().
 **********************************************************************************************************************/
void ui_service_unlock(ui_service_instance_ctrl_t *const p_ctrl)
{
    if ((NULL != p_ctrl) && p_ctrl->init)
    {
        lvgl_port_unlock(p_ctrl->p_cfg->p_lvgl);
    }
}
